css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; display: grid; place-items: center; }
.loader span { position: absolute; width: 22%; height: 22%; border-radius: 50%; background: radial-gradient(circle at 40% 35%, color-mix(in srgb, #fff 22%, var(--accent)), var(--accent)); animation: ink calc(var(--loader-speed) * 2.2) ease-out infinite; }
.loader span:nth-child(2) { background: radial-gradient(circle at 40% 35%, color-mix(in srgb, #fff 22%, var(--accent-2)), var(--accent-2)); animation-delay: calc(var(--loader-speed) * 1.1); }
@keyframes ink { 0% { transform: scale(.2); border-radius: 50%; opacity: 1; } 55% { border-radius: 42% 58% 45% 55%; } 100% { transform: scale(3.4); border-radius: 46% 54% 52% 48%; opacity: 0; } }
